class Job:
    def __init__(self, thread, release_time, deadline):
        self.thread = thread
        self.release_time = release_time
        self.deadline = deadline
        self.completion_time = None

def calculate_utilization(task_set):
    U_total = 0.0
    for task_i in task_set:
        U_total += task_i.C / task_i.T
    return U_total

def is_utilization_feasible(task_set):
    return calculate_utilization(task_set) <= 1.0

class Thread:
    def __init__(self, thread_id, execution_time, ...):
        self.thread_id = thread_id
        self.execution_time = execution_time
        self.predecessors = [] # List of (predecessor_thread, suspension_delay)

    def check_start_condition(self, current_time, k_instance):
        for pred_thread, delta_delay in self.predecessors:
            pred_completion_time = pred_thread.get_completion_time(k_instance)
            if current_time < pred_completion_time + delta_delay:
                return False # Cannot start yet
        return True # All suspension delays respected

